css:
.mag-cookie-wrapper {
  position: fixed;
  bottom: -150px;
  left: 20px;
  z-index: 10000;
  max-width: 450px;
  background-color: var(--bs-tertiary-bg, #1a1a1a);
  border: 1px solid var(--border-color, #333);
  border-radius: var(--radius, 12px);
  box-shadow: 0 15px 35px rgba(0,0,0,0.15);
  padding: 1.5rem;
  opacity: 0;
  visibility: hidden;
  transition: all 0.5s cubic-bezier(0.16, 1, 0.3, 1);
  font-family: var(--font-body, 'Inter', sans-serif);
}
.mag-cookie-wrapper.show {
  bottom: 20px;
  opacity: 1;
  visibility: visible;
}
.mag-cookie-content strong {
  font-family: var(--font-title, 'Playfair Display', serif);
  font-size: 1.1rem;
  color: var(--mag-title, #fff);
  display: block;
  margin-bottom: 0.5rem;
}
.mag-cookie-content p {
  font-size: 0.85rem;
  color: rgba(255,255,255,0.7);
  line-height: 1.5;
  margin-bottom: 1.2rem;
}
.cookie-buttons {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}
.btn-cookie-link {
  font-size: 0.85rem;
  color: var(--mag-secondary, #6c757d);
  text-decoration: underline;
  text-underline-offset: 4px;
  transition: color 0.2s ease;
}
.btn-cookie-link:hover { color: var(--mag-primary, #0d6efd); }
.btn-cookie-accept {
  background-color: var(--mag-primary, #0d6efd);
  color: #fff;
  border: none;
  padding: 10px 20px;
  border-radius: 6px;
  font-weight: 700;
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  cursor: pointer;
  transition: transform 0.2s ease, opacity 0.2s ease;
}
.btn-cookie-accept:hover { opacity: 0.9; transform: translateY(-2px); }
@media (max-width: 768px) {
  .mag-cookie-wrapper { left: 15px; right: 15px; max-width: 100%; }
  .cookie-buttons { flex-direction: column; }
  .btn-cookie-accept { width: 100%; order: -1; }
  .btn-cookie-link { margin-top: 10px; }
}

javascript:
document.addEventListener('DOMContentLoaded', function() {
  const cookieBanner = document.getElementById('mag-cookie-banner');
  const acceptBtn = document.getElementById('mag-cookie-accept');

  if (!localStorage.getItem('magConsent')) {
    setTimeout(() => {
      cookieBanner.classList.add('show');
    }, 1500);
  }

  acceptBtn.addEventListener('click', function() {
    localStorage.setItem('magConsent', 'accepted');
    cookieBanner.classList.remove('show');
    setTimeout(() => {
      cookieBanner.remove();
    }, 500);
  });
});
